"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { readableColor } from "@/lib/format";
import CRESTS from "@/lib/crests.json";

const SIZES = {
  xs: "size-5 text-[9px]",
  sm: "size-7 text-[10px]",
  md: "size-9 text-xs",
  lg: "size-12 text-sm",
  xl: "size-16 text-lg",
};

const CREST_MAP = CRESTS as Record<string, string>;

/**
 * A clean, crest-style club badge.
 *
 * When a real, free crest URL is known for the club (see `src/lib/crests.json`,
 * generated by `ml/club_crests.py` from the free, key-less TheSportsDB /
 * football-data CDNs) it is hot-linked as an `<img>` — no trademarked image is
 * ever committed to the repo. If the crest can't load (offline, CDN hiccup, or
 * an unmapped club) it gracefully falls back to a tasteful two-tone monogram
 * built from the club's official primary/secondary colours — always legal,
 * always renders, never breaks.
 */
export function ClubBadge({
  code,
  primary,
  secondary,
  crest,
  size = "md",
  className,
}: {
  code: string;
  primary: string;
  secondary: string;
  crest?: string | null;
  size?: keyof typeof SIZES;
  className?: string;
}) {
  const [broken, setBroken] = React.useState(false);
  const url = crest ?? CREST_MAP[code] ?? null;

  if (url && !broken) {
    return (
      <span
        className={cn(
          "inline-flex shrink-0 items-center justify-center overflow-hidden rounded-md bg-white p-0.5 shadow-sm ring-1 ring-black/10",
          SIZES[size],
          className,
        )}
        title={code}
      >
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img
          src={url}
          alt={`${code} crest`}
          loading="lazy"
          decoding="async"
          className="h-full w-full object-contain"
          onError={() => setBroken(true)}
        />
      </span>
    );
  }

  const p = readableColor(primary || "#334155");
  const s = secondary || "#0f172a";
  return (
    <span
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center rounded-md font-bold uppercase tracking-tight text-white shadow-sm ring-1 ring-black/10",
        SIZES[size],
        className,
      )}
      style={{ backgroundImage: `linear-gradient(135deg, ${p} 0%, ${p} 55%, ${s} 55%, ${s} 100%)` }}
      aria-hidden
    >
      <span className="drop-shadow-[0_1px_1px_rgba(0,0,0,0.4)]">{code}</span>
    </span>
  );
}
